<?php
declare(strict_types=1);

// Webhook de Wompi.
// Recibe notificaciones de pagos y actualiza suscripciones o mensajes de estado.
require __DIR__.'/../config/database.php';
header('Content-Type: application/json; charset=utf-8');
function webhook_done(int $status,string $message): never { http_response_code($status);echo json_encode(['ok'=>$status>=200&&$status<300,'message'=>$message]);exit; }
if($_SERVER['REQUEST_METHOD']!=='POST')webhook_done(405,'POST required');
$secret=(string)getenv('PROSSOR_WOMPI_EVENT_SECRET');if($secret==='')webhook_done(503,'Webhook no configurado');
$raw=file_get_contents('php://input');if(strlen($raw)>131072)webhook_done(413,'Payload demasiado grande');
try{$event=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}catch(Throwable){webhook_done(400,'JSON inválido');}
if(($event['event']??'')!=='transaction.updated'||!is_array($event['data']['transaction']??null))webhook_done(202,'Evento ignorado');
$sig=$event['signature']??[];$properties=$sig['properties']??[];$checksum=(string)($sig['checksum']??'');if(!is_array($properties)||!$properties||$checksum==='')webhook_done(401,'Firma ausente');
$lookup=static function(array $root,string $path): string { $v=$root;foreach(explode('.',$path,$path) as $key){if(!is_array($v)||!array_key_exists($key,$v))return ''; $v=$v[$key];}return is_scalar($v)?(string)$v:''; };
$base='';foreach($properties as $path){if(!is_string($path))webhook_done(401,'Firma inválida');$value=$lookup($event['data'],$path);if($value==='')webhook_done(401,'Propiedad de firma ausente');$base.=$value;}$base.=(string)($event['timestamp']??'').$secret;$expected=strtoupper(hash('sha256',$base));$provided=strtoupper($checksum);$header=(string)($_SERVER['HTTP_X_EVENT_CHECKSUM']??'');if(!hash_equals($expected,$provided)||($header!==''&&!hash_equals($expected,strtoupper($header))))webhook_done(401,'Firma inválida');
$tx=$event['data']['transaction'];$ref=(string)($tx['reference']??'');$txid=(string)($tx['id']??'');$state=strtoupper((string)($tx['status']??''));$eventId=$txid.':'.$state.':'.(string)($event['timestamp']??'');$env=($event['environment']??'')==='prod'?'prod':'test';if($ref===''||$txid===''||!in_array($state,['APPROVED','DECLINED','VOIDED','ERROR','PENDING'],true))webhook_done(400,'Transacción incompleta');
try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT id,user_id,subscription_id,amount_in_cents,environment,status FROM payment_orders WHERE reference=? FOR UPDATE');$q->execute([$ref]);$order=$q->fetch();if(!$order||$order['environment']!==$env||(int)$order['amount_in_cents']!==(int)($tx['amount_in_cents']??-1)||($tx['currency']??'')!=='COP')throw new RuntimeException('Orden no coincide');
  $pdo->prepare("INSERT IGNORE INTO payment_webhook_events(provider,event_id,payload_hash,status) VALUES('wompi',?,?, 'verified')")->execute([$eventId,hash('sha256',$raw)]);if($pdo->lastInsertId()==='0'){$pdo->commit();webhook_done(200,'Evento ya procesado');}if($order['status']!=='pending'){$pdo->prepare("UPDATE payment_webhook_events SET status='processed',processed_at=NOW() WHERE provider='wompi' AND event_id=?")->execute([$eventId]);$pdo->commit();webhook_done(200,'Orden ya finalizada');}
  $mapped=['APPROVED'=>'approved','DECLINED'=>'declined','VOIDED'=>'voided','ERROR'=>'error','PENDING'=>'pending'][$state];$pdo->prepare('UPDATE payment_orders SET status=?,provider_transaction_id=? WHERE id=?')->execute([$mapped,$txid,$order['id']]);$pdo->prepare('INSERT INTO payment_transactions(subscription_id,provider,status,amount_cop,reference) VALUES(?,?,?,?,?)')->execute([$order['subscription_id'],'wompi',$mapped,(int)ceil((int)$order['amount_in_cents']/100),$ref]);
  if($state==='APPROVED'&&$order['status']==='pending'){$plan=$pdo->prepare('SELECT p.duration_days FROM user_subscriptions s JOIN subscription_plans p ON p.id=s.plan_id WHERE s.id=?');$plan->execute([$order['subscription_id']]);$days=$plan->fetchColumn();if($days===null)$pdo->prepare("UPDATE user_subscriptions SET status='active',starts_at=CURDATE(),ends_at=NULL WHERE id=? AND status='pending'")->execute([$order['subscription_id']]);else $pdo->prepare("UPDATE user_subscriptions SET status='active',starts_at=CURDATE(),ends_at=DATE_ADD(CURDATE(),INTERVAL ? DAY) WHERE id=? AND status='pending'")->execute([(int)$days,$order['subscription_id']]);}
  $pdo->prepare("UPDATE payment_webhook_events SET status='processed',processed_at=NOW() WHERE provider='wompi' AND event_id=?")->execute([$eventId]);$details=json_encode(['order_id'=>(int)$order['id'],'status'=>$mapped],JSON_UNESCAPED_UNICODE);$pdo->prepare("INSERT INTO audit_logs(user_id,event,details,ip_address) VALUES(?,'payment.webhook_processed',?,?)")->execute([(int)$order['user_id'],$details,substr((string)($_SERVER['REMOTE_ADDR']??''),0,45)]);$pdo->commit();webhook_done(200,'Procesado');
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Prossor Wompi webhook rejected: '.get_class($e));webhook_done(400,'No se pudo validar o procesar la orden');}
